//! Sphere-specific debug RPC extensions.
#![allow(clippy::double_must_use)] // Async methods generated by `async_trait` and `rpc` add `must_use`.

use alloy_rpc_types_eth::BlockId;
use jsonrpsee::{core::RpcResult, proc_macros::rpc};

use crate::types::SphereExecutionWitness;

/// In-process Sphere debug API contract.
#[jsonrpsee::core::async_trait]
pub trait SphereDebugApi: Send + Sync {
    /// Replays a Sphere block and returns its Sphere and Arc L1 state witnesses.
    /// Fails if the node's L1 provider cannot supply the required historical proofs.
    async fn sphere_execution_witness(&self, block: BlockId) -> RpcResult<SphereExecutionWitness>;
}

/// JSON-RPC transport adapter for [`SphereDebugApi`].
#[rpc(server, namespace = "debug")]
pub trait SphereDebugApiRpc {
    /// Replays a Sphere block and returns its Sphere and Arc L1 state witnesses.
    /// Fails if the node's L1 provider cannot supply the required historical proofs.
    #[method(name = "sphereExecutionWitness")]
    async fn sphere_execution_witness(&self, block: BlockId) -> RpcResult<SphereExecutionWitness>;
}

#[jsonrpsee::core::async_trait]
impl<T> SphereDebugApiRpcServer for T
where
    T: SphereDebugApi + 'static,
{
    async fn sphere_execution_witness(&self, block: BlockId) -> RpcResult<SphereExecutionWitness> {
        SphereDebugApi::sphere_execution_witness(self, block).await
    }
}
